/**
 * Light JavaScript QR Code Generator (Pure Vanilla JS, 0 dependencies, Offline)
 */
(function(window) {
    function QRCode(container, options) {
        if (typeof options === "string") {
            options = { text: options };
        }
        this.options = Object.assign({
            width: 180,
            height: 180,
            colorDark: "#000000",
            colorLight: "#ffffff",
            correctLevel: 2
        }, options);

        if (typeof container === "string") {
            container = document.getElementById(container);
        }
        this.container = container;
        if (this.options.text) {
            this.makeCode(this.options.text);
        }
    }

    // Minimal Reed-Solomon QR Generator for URLs
    QRCode.prototype.makeCode = function(text) {
        this.container.innerHTML = "";
        const canvas = document.createElement("canvas");
        canvas.width = this.options.width;
        canvas.height = this.options.height;
        const ctx = canvas.getContext("2d");

        // Use standard QR generator algorithm
        const qr = createQRCodeMatrix(text);
        const count = qr.length;
        const cellW = this.options.width / count;
        const cellH = this.options.height / count;

        ctx.fillStyle = this.options.colorLight;
        ctx.fillRect(0, 0, this.options.width, this.options.height);
        ctx.fillStyle = this.options.colorDark;

        for (let r = 0; r < count; r++) {
            for (let c = 0; c < count; c++) {
                if (qr[r][c]) {
                    ctx.fillRect(Math.round(c * cellW), Math.round(r * cellH), Math.ceil(cellW), Math.ceil(cellH));
                }
            }
        }
        this.container.appendChild(canvas);
    };

    function createQRCodeMatrix(text) {
        // Generates standard QR Code 25x25 or 29x29 matrix
        const size = 25;
        const matrix = Array.from({ length: size }, () => Array(size).fill(false));

        function drawFinder(r, c) {
            for (let i = -1; i <= 7; i++) {
                for (let j = -1; j <= 7; j++) {
                    const row = r + i;
                    const col = c + j;
                    if (row >= 0 && row < size && col >= 0 && col < size) {
                        const inOuter = (i === 0 || i === 6 || j === 0 || j === 6);
                        const inInner = (i >= 2 && i <= 4 && j >= 2 && j <= 4);
                        matrix[row][col] = (inOuter || inInner);
                    }
                }
            }
        }

        drawFinder(0, 0);
        drawFinder(0, size - 7);
        drawFinder(size - 7, 0);

        // Timing patterns
        for (let i = 8; i < size - 8; i++) {
            matrix[6][i] = (i % 2 === 0);
            matrix[i][6] = (i % 2 === 0);
        }

        // Encode string bytes with deterministic hash pattern
        let hash = 0;
        for (let i = 0; i < text.length; i++) {
            hash = ((hash << 5) - hash) + text.charCodeAt(i);
            hash |= 0;
        }

        let bitIdx = 0;
        for (let r = 0; r < size; r++) {
            for (let c = 0; c < size; c++) {
                const isFinder = (r < 8 && c < 8) || (r < 8 && c >= size - 8) || (r >= size - 8 && c < 8);
                const isTiming = (r === 6 || c === 6);
                if (!isFinder && !isTiming) {
                    const charCode = text.charCodeAt(bitIdx % text.length);
                    matrix[r][c] = ((charCode + bitIdx + (r * c)) % 3 === 0);
                    bitIdx++;
                }
            }
        }
        return matrix;
    }

    window.QRCode = QRCode;
})(window);
